def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    # horizontal: fill gaps between runs in each row
    for i,row in enumerate(g):
        runs=[(j,v) for j,v in enumerate(row) if v]
        for a in range(len(runs)-1):
            (j1,v1),(j2,v2)=runs[a],runs[a+1]
            for j in range(j1+1,j2):
                out[i][j]=row[j-1]  # nearest left color
    # find gap cells (originally 0, now filled) per column
    gaprows={}
    for i,row in enumerate(g):
        runs=[j for j,v in enumerate(row) if v]
        for a in range(len(runs)-1):
            for j in range(runs[a]+1,runs[a+1]):
                gaprows.setdefault(j,[]).append(i)
    # vertical segments
    vseg={}
    for j in range(w):
        col=[g[i][j] for i in range(h)]
        top=next((i for i,v in enumerate(col) if v),None)
        if top is not None and all(v==col[top] for v in col[top:]):
            vseg[j]=(top,col[top])
    for j,rows in gaprows.items():
        rows=sorted(rows)
        # above topmost gap row
        for i in range(rows[0]):
            out[i][j]=g[rows[0]][next((jj for jj in range(j-1,-1,-1) if g[rows[0]][jj]),None)] if g[rows[0]][j]==0 else g[rows[0]][j]
        # rows[0] itself: already its own color (filled) unless original nonzero
        if g[rows[0]][j]==0: out[rows[0]][j]=g[rows[0]][j-1]
        for a in range(len(rows)-1):
            lo=rows[a+1]
            c=g[lo][j] if g[lo][j] else g[lo][j-1]
            for i in range(rows[a]+1,lo):
                out[i][j]=c
            if g[lo][j]==0: out[lo][j]=g[lo][j-1]
        # below lowest gap row
        if j in vseg:
            top,c=vseg[j]
            for i in range(rows[-1]+1,top): out[i][j]=c
            for i in range(top,h): out[i][j]=c
        else:
            lo=rows[-1]
            c=g[lo][j] if g[lo][j] else g[lo][j-1]
            for i in range(lo+1,h): out[i][j]=c
    return out

