def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    def runs_of(seq):
        r=[];s=None
        for i,v in enumerate(seq):
            if v and s is None: s=i
            if not v and s is not None: r.append((s,i-1)); s=None
        if s is not None: r.append((s,len(seq)-1))
        return r
    longrows={i for i,row in enumerate(g) if any(b-a+1>=2 for a,b in runs_of(row))}
    # vertical segments: contiguous column runs among cells in non-long rows
    vseg={}
    for j in range(w):
        cells=[i for i in range(h) if g[i][j] and i not in longrows]
        for a,b in runs_of([1 if i in set(cells) else 0 for i in range(h)]):
            rows=[i for i in range(a,b+1) if i in set(cells)]
            if rows: vseg[j]=(rows[0],g[rows[0]][j])
    def rowfill(i,j):  # color gap at (i,j) gets from its row
        row=g[i]; k=j-1
        while row[k]==0: k-=1
        return row[k]
    gaprows={}
    for i in longrows:
        rr=runs_of(g[i])
        for (a1,b1),(a2,b2) in zip(rr,rr[1:]):
            for j in range(b1+1,a2):
                out[i][j]=rowfill(i,j); gaprows.setdefault(j,[]).append(i)
    for j,rows in gaprows.items():
        rows=sorted(rows)
        c0=rowfill(rows[0],j)
        for i in range(rows[0]): out[i][j]=c0
        for a in range(len(rows)-1):
            lo=rows[a+1]; c=rowfill(lo,j)
            for i in range(rows[a]+1,lo): out[i][j]=c
        if j in vseg:
            top,c=vseg[j]
            for i in range(rows[-1]+1,top): out[i][j]=c
        else:
            c=rowfill(rows[-1],j)
            for i in range(rows[-1]+1,h): out[i][j]=c
    return out

