def row_runs(grid):
    """Indices of rows containing a nonzero run of length >= 2 (horizontal line rows)."""
    return {i for i,row in enumerate(grid) if any(b-a+1>=2 for a,b in runs(row))}

def fill_row_gaps(grid):
    """In each row, cells between two nonzero runs take the color of the run to their left."""
